// No console window in any build.
#![windows_subsystem = "windows"]

// Generated by BindingsGenerator from BindingsGenerator/Filters.txt. Don't edit by hand.
#[path = "Bindings.rs"]
#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    clippy::all
)]
mod bindings;

// Written by hand from GameInput.h, keeping its native names.
#[path = "GameInput.rs"]
#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code
)]
mod game_input;

#[path = "Canvas.rs"]
mod canvas;
#[path = "Font.rs"]
mod font;
#[path = "FrameCounter.rs"]
mod frame_counter;
#[path = "Input.rs"]
mod input;
#[path = "Panels.rs"]
mod panels;
#[path = "Renderer.rs"]
mod renderer;

use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};

use bindings::*;
use canvas::Canvas;
use font::Font;
use frame_counter::FrameCounter;
use input::Input;
use renderer::{Renderer, check_handle};
use windows_core::{Error, PCWSTR, Result, w};

// The em height of the font at 100% scaling, in pixels.
const FONT_SIZE: u32 = 15;
// The smallest window, at 100% scaling, that the panels fit in.
const MINIMUM_WINDOW_SIZE: [u32; 2] = [1024, 820];

// The window procedure only records what happened; the main loop reacts.
// This keeps renderer state out of the callback.
static CLIENT_WIDTH: AtomicU32 = AtomicU32::new(0);
static CLIENT_HEIGHT: AtomicU32 = AtomicU32::new(0);
static RESIZED: AtomicBool = AtomicBool::new(false);
static DPI: AtomicU32 = AtomicU32::new(USER_DEFAULT_SCREEN_DPI as u32);
static DPI_CHANGED: AtomicBool = AtomicBool::new(false);

extern "system" fn window_procedure(
    window: HWND,
    message: u32,
    wparam: WPARAM,
    lparam: LPARAM,
) -> LRESULT {
    match message as i32 {
        WM_SIZE => {
            CLIENT_WIDTH.store((lparam.0 & 0xFFFF) as u32, Ordering::Relaxed);
            CLIENT_HEIGHT.store(((lparam.0 >> 16) & 0xFFFF) as u32, Ordering::Relaxed);
            RESIZED.store(true, Ordering::Relaxed);
            LRESULT(0)
        }
        // The window moved to a monitor with another scale. Take the size
        // Windows suggests for it, and redraw the font at the new size.
        WM_DPICHANGED => {
            DPI.store((wparam.0 & 0xFFFF) as u32, Ordering::Relaxed);
            DPI_CHANGED.store(true, Ordering::Relaxed);
            let suggested = unsafe { &*(lparam.0 as *const RECT) };
            unsafe {
                let _ = SetWindowPos(
                    window,
                    None,
                    suggested.left,
                    suggested.top,
                    suggested.right - suggested.left,
                    suggested.bottom - suggested.top,
                    (SWP_NOZORDER | SWP_NOACTIVATE) as u32,
                );
            }
            LRESULT(0)
        }
        WM_GETMINMAXINFO => {
            let info = unsafe { &mut *(lparam.0 as *mut MINMAXINFO) };
            let dpi = unsafe { GetDpiForWindow(window) };
            let [width, height] = MINIMUM_WINDOW_SIZE
                .map(|size| (size * dpi).div_ceil(USER_DEFAULT_SCREEN_DPI as u32) as i32);
            info.ptMinTrackSize = POINT {
                x: width,
                y: height,
            };
            LRESULT(0)
        }
        // A tap of Alt or F10 would otherwise enter the window menu's modal
        // loop, which stalls the frame loop until the next key press.
        WM_SYSCOMMAND if (wparam.0 & 0xFFF0) as i32 == SC_KEYMENU => LRESULT(0),
        WM_DESTROY => {
            unsafe { PostQuitMessage(0) };
            LRESULT(0)
        }
        _ => unsafe { DefWindowProcW(window, message, wparam, lparam) },
    }
}

fn font_pixel_height(dpi: u32) -> i32 {
    (FONT_SIZE * dpi).div_ceil(USER_DEFAULT_SCREEN_DPI as u32) as i32
}

fn main() -> Result<()> {
    unsafe {
        // Without this, Windows bitmap-stretches the window on high-DPI displays.
        SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2).ok()?;

        let instance = GetModuleHandleW(PCWSTR::null());
        check_handle(instance.0)?;
        let cursor = LoadCursorW(None, IDC_ARROW);
        check_handle(cursor.0)?;

        let class_name = w!("MainWindow");
        let class = WNDCLASSEXW {
            cbSize: size_of::<WNDCLASSEXW>() as u32,
            style: (CS_HREDRAW | CS_VREDRAW) as u32,
            lpfnWndProc: Some(window_procedure),
            hInstance: instance,
            hCursor: cursor,
            lpszClassName: class_name,
            ..Default::default()
        };
        if RegisterClassExW(&class).0 == 0 {
            return Err(Error::from_thread());
        }

        // 1280x900 at 100% scaling, but no more than 90% of the screen.
        let scale = GetDpiForSystem() as f32 / USER_DEFAULT_SCREEN_DPI as f32;
        let width = (1280.0 * scale).min(GetSystemMetrics(SM_CXSCREEN) as f32 * 0.9);
        let height = (900.0 * scale).min(GetSystemMetrics(SM_CYSCREEN) as f32 * 0.9);
        let window = CreateWindowExW(
            0,
            class_name,
            w!("GameInput Demo"),
            (WS_OVERLAPPEDWINDOW | WS_VISIBLE) as u32,
            CW_USEDEFAULT,
            CW_USEDEFAULT,
            width as i32,
            height as i32,
            None,
            None,
            Some(instance),
            None,
        );
        check_handle(window.0)?;
        DPI.store(GetDpiForWindow(window), Ordering::Relaxed);
        // Cosmetic, so a failure doesn't matter.
        let dark = windows_core::BOOL(1);
        let _ = DwmSetWindowAttribute(
            window,
            DWMWA_USE_IMMERSIVE_DARK_MODE as u32,
            &raw const dark as _,
            size_of::<windows_core::BOOL>() as u32,
        );

        let mut font = Font::new(font_pixel_height(DPI.load(Ordering::Relaxed)))?;
        let mut renderer = Renderer::new(window, &font)?;
        // Without GameInput the window still opens, and says why there's no input.
        let mut input =
            Input::new().map_err(|error| format!("{} ({})", error.message(), error.code()));
        let mut frames = FrameCounter::default();
        let mut vertices = Vec::new();

        let mut message = MSG::default();
        loop {
            // Drain all pending messages, then render one frame once the
            // renderer is ready for it.
            while PeekMessageW(&mut message, None, 0, 0, PM_REMOVE as u32).as_bool() {
                if message.message == WM_QUIT as u32 {
                    return Ok(());
                }
                let _ = TranslateMessage(&message);
                DispatchMessageW(&message);
            }

            if DPI_CHANGED.swap(false, Ordering::Relaxed) {
                font = Font::new(font_pixel_height(DPI.load(Ordering::Relaxed)))?;
                renderer.set_font(&font)?;
            }
            if RESIZED.swap(false, Ordering::Relaxed) {
                renderer.resize(
                    CLIENT_WIDTH.load(Ordering::Relaxed),
                    CLIENT_HEIGHT.load(Ordering::Relaxed),
                )?;
            }

            if IsIconic(window).as_bool() {
                // Minimized: sleep until something happens instead of spinning.
                WaitMessage().ok()?;
                frames.pause();
                continue;
            }

            // Spin until the GPU and DXGI can take a frame. Blocking on an
            // event would instead wait for Windows to wake the thread, which
            // can take a while if its core went into a power-saving state.
            // The wait is short, because frames don't wait for vertical sync,
            // and the loop keeps handling window messages through it.
            if !renderer.is_ready()? {
                std::hint::spin_loop();
                continue;
            }

            // Read input only now, right before drawing, so the frame shows
            // the newest readings.
            frames.frame();
            if let Ok(input) = &mut input {
                input.update();
            }
            let focused = GetForegroundWindow() == window;
            let mut canvas = Canvas::new(&font, &mut vertices);
            panels::draw(
                &mut canvas,
                &input,
                focused,
                &frames,
                renderer.width as f32,
                renderer.height as f32,
            );
            renderer.render(&canvas.vertices, panels::BACKGROUND)?;
        }
    }
}
